+      unawaited(subscription.cancel().then((_) {}, onError: (Object _) {}));
+      throw TimeoutException(
+        'provider fetch ($endpoint): response did not complete within '
+        '${read.inSeconds}s (read watchdog; FA_PROVIDER_TIMEOUT_SECONDS '
+        'overrides this)',
